package com.nattechnologies.trastcms.plugins.pay.cleanpay;
import jakarta.persistence.*;import org.hibernate.annotations.TenantId;
@Entity @Table(name="commerce_cleanpay_settings",uniqueConstraints=@UniqueConstraint(name="uk_cleanpay_site",columnNames="site_id"))
public class CleanPaySettings{@Id @GeneratedValue(strategy=GenerationType.IDENTITY)private Long id;@TenantId @Column(name="site_id",nullable=false,length=80)private String siteId;private boolean enabled;@Column(name="api_url",length=1000)private String apiUrl;@Column(name="status_url",length=1000)private String statusUrl;@Column(name="merchant_id",length=200)private String merchantId;@Column(name="terminal_id",length=200)private String terminalId;@Column(name="auth_header",length=100)private String authHeader="Authorization";@Column(name="auth_scheme",length=40)private String authScheme="Bearer";@Lob @Column(name="token_encrypted")private String tokenEncrypted;@Column(name="three_ds_enabled",nullable=false)private boolean threeDsEnabled=true;@Column(name="return_url",length=1000)private String returnUrl;@Column(name="cancel_url",length=1000)private String cancelUrl;@Column(name="timeout_seconds",nullable=false)private int timeoutSeconds=30;@Lob @Column(name="additional_json")private String additionalJson;
public Long getId(){return id;}public String getSiteId(){return siteId;}public boolean isEnabled(){return enabled;}public void setEnabled(boolean v){enabled=v;}public String getApiUrl(){return apiUrl;}public void setApiUrl(String v){apiUrl=v;}public String getStatusUrl(){return statusUrl;}public void setStatusUrl(String v){statusUrl=v;}public String getMerchantId(){return merchantId;}public void setMerchantId(String v){merchantId=v;}public String getTerminalId(){return terminalId;}public void setTerminalId(String v){terminalId=v;}public String getAuthHeader(){return authHeader;}public void setAuthHeader(String v){authHeader=v;}public String getAuthScheme(){return authScheme;}public void setAuthScheme(String v){authScheme=v;}public String getTokenEncrypted(){return tokenEncrypted;}public void setTokenEncrypted(String v){tokenEncrypted=v;}public boolean isThreeDsEnabled(){return threeDsEnabled;}public void setThreeDsEnabled(boolean v){threeDsEnabled=v;}public String getReturnUrl(){return returnUrl;}public void setReturnUrl(String v){returnUrl=v;}public String getCancelUrl(){return cancelUrl;}public void setCancelUrl(String v){cancelUrl=v;}public int getTimeoutSeconds(){return timeoutSeconds;}public void setTimeoutSeconds(int v){timeoutSeconds=Math.max(5,Math.min(120,v));}public String getAdditionalJson(){return additionalJson;}public void setAdditionalJson(String v){additionalJson=v;}}
